1: /**
2:  * TransformationDetector — detects stage-transition thresholds.
3:  * Spec: foundations/17 §2
4:  */
5: import type { Line } from '../domain/Line.js';
6: import { ALL_LINES } from '../domain/Line.js';
7: import type { Stage } from '../domain/Stage.js';
8: import { ALL_STAGES, stageOrdinal } from '../domain/Stage.js';
9: import type { Significator } from '../domain/Significator.js';
10: 
11: export interface TransformationSignal {
12:   readonly targetStage: Stage;
13:   readonly readiness: number; // 0-1
14:   readonly convergentLines: readonly Line[];
15:   readonly blockers: readonly string[];
16: }
17: 
18: export interface ReadinessReport {
19:   readonly convergence: number; // fraction of lines at edge
20:   readonly saturation: number; // catalyst processed ratio
21:   readonly shadowClearance: number; // 0-1, 1 = no blocking shadows
22:   readonly overall: number; // weighted composite
23: }
24: 
25: // Lines required at edge for each stage transition
26: const CONVERGENCE_REQUIREMENTS: Record<number, number> = {
27:   0: 3, // Infrared→Magenta: 3 lines
28:   1: 4, // Magenta→Red: 4 lines
29:   2: 5, // Red→Amber: 5 lines
30:   3: 5, // Amber→Orange
31:   4: 6, // Orange→Green
32:   5: 6, // Green→Turquoise
33:   6: 7, // Turquoise→White
34: };
35: 
36: const SATURATION_THRESHOLD = 20; // encounters per line at current stage
37: 
38: /** Detect whether transformation threshold is crossed. */
39: export function detectThreshold(sig: Significator): TransformationSignal | null {
40:   const currentOrd = stageOrdinal(sig.currentStage);
41:   if (currentOrd >= ALL_STAGES.length - 1) return null; // already at White
42: 
43:   const targetStage = ALL_STAGES[currentOrd + 1]!;
44:   const report = computeReadiness(sig, targetStage);
45: 
46:   if (report.overall >= 0.8) {
47:     const convergentLines = ALL_LINES.filter(l => stageOrdinal(sig.altitudes[l]) >= currentOrd);
48:     const blockers: string[] = [];
49:     if (report.shadowClearance < 0.8) blockers.push('unresolved_critical_shadows');
50:     if (report.convergence < 0.7) blockers.push('insufficient_line_convergence');
51: 
52:     if (blockers.length === 0) {
53:       return { targetStage, readiness: report.overall, convergentLines, blockers };
54:     }
55:   }
56: 
57:   return null;
58: }
59: 
60: /** Compute readiness for a specific stage transition. */
61: export function computeReadiness(sig: Significator, targetStage: Stage): ReadinessReport {
62:   const targetOrd = stageOrdinal(targetStage);
63:   const currentOrd = targetOrd - 1;
64:   const required = CONVERGENCE_REQUIREMENTS[currentOrd] ?? 5;
65: 
66:   // Convergence: how many lines are at or above current stage
67:   const linesAtEdge = ALL_LINES.filter(l => stageOrdinal(sig.altitudes[l]) >= currentOrd);
68:   const convergence = Math.min(1, linesAtEdge.length / required);
69: 
70:   // Saturation: encounters processed at current stage
71:   let totalTraces = 0;
72:   for (const line of ALL_LINES) {
73:     const key = `${line}:${ALL_STAGES[currentOrd]}`;
74:     const cell = sig.polarity.cells[key];
75:     totalTraces += cell?.traceCount ?? 0;
76:   }
77:   const saturation = Math.min(1, totalTraces / (ALL_LINES.length * SATURATION_THRESHOLD));
78: 
79:   // Shadow clearance: no critical unresolved shadows at current stage
80:   const criticalShadows = sig.shadows.entries.filter(
81:     e => e.resolvedAt === null && e.severity >= 0.7 && stageOrdinal(e.stage) >= currentOrd,
82:   );
83:   const shadowClearance = criticalShadows.length === 0 ? 1 : Math.max(0, 1 - criticalShadows.length * 0.3);
84: 
85:   const overall = convergence * 0.4 + saturation * 0.3 + shadowClearance * 0.3;
86: 
87:   return { convergence, saturation, shadowClearance, overall };
88: }
89: 
90: // ─── Transformation State Machine (R3.1 + R3.5 + R3.6) ───
91: 
92: export type TransformationPhase = 'idle' | 'threshold' | 'unravelling' | 'crucible' | 'emergence' | 'complete';
93: 
94: export interface TransformationState {
95:   readonly phase: TransformationPhase;
96:   readonly targetStage: Stage | null;
97:   readonly sessionsInPhase: number;
98:   readonly knotsResolved: number;
99:   readonly totalKnots: number;
100: }
101: 
102: export function createInitialTransformationState(): TransformationState {
103:   return { phase: 'idle', targetStage: null, sessionsInPhase: 0, knotsResolved: 0, totalKnots: 0 };
104: }
105: 
106: /**
107:  * Advance the transformation state machine based on current conditions.
108:  * Called after each encounter during an active transformation.
109:  */
110: export function advanceTransformation(
111:   state: TransformationState,
112:   sig: Significator,
113: ): TransformationState {
114:   switch (state.phase) {
115:     case 'idle': {
116:       const signal = detectThreshold(sig);
117:       if (signal && signal.readiness >= 0.8) {
118:         return { ...state, phase: 'threshold', targetStage: signal.targetStage, sessionsInPhase: 0, totalKnots: signal.blockers.length || 1 };
119:       }
120:       return state;
121:     }
122:     case 'threshold': {
123:       if (state.sessionsInPhase >= 1) {
124:         return { ...state, phase: 'unravelling', sessionsInPhase: 0 };
125:       }
126:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
127:     }
128:     case 'unravelling': {
129:       if (state.sessionsInPhase >= 2) {
130:         return { ...state, phase: 'crucible', sessionsInPhase: 0 };
131:       }
132:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
133:     }
134:     case 'crucible': {
135:       if (state.knotsResolved >= state.totalKnots || state.sessionsInPhase >= 5) {
136:         return { ...state, phase: 'emergence', sessionsInPhase: 0 };
137:       }
138:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
139:     }
140:     case 'emergence': {
141:       if (state.sessionsInPhase >= 1) {
142:         return { ...state, phase: 'complete' };
143:       }
144:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
145:     }
146:     case 'complete':
147:       return state;
148:   }
149: }
150: 
151: /**
152:  * Record a knot resolution during the crucible phase.
153:  */
154: export function recordKnotResolution(state: TransformationState): TransformationState {
155:   if (state.phase !== 'crucible') return state;
156:   return { ...state, knotsResolved: state.knotsResolved + 1 };
157: }
158: 
159: /**
160:  * Commit the transformation: returns the new target stage.
161:  * Only valid when phase === 'complete'.
162:  * The caller is responsible for advancing the Significator's altitude.
163:  */
