436:         cooldown: {
437:           intensityCeiling: 0.2,
438:           integrationFocus: true,
439:           preferredModalities: ['LanguageReflective'],
440:         },
441:       };
442: 
443:     case 'polarity-deepening':
444:       return {
445:         warmup: {
446:           intensityCeiling: 0.3,
447:           focus: 'familiar-modality',
448:           preferredModalities: ['ScenarioChoice', 'LanguageReflective'],
449:         },
450:         peak: {
451:           intensityRange: { min: 0.5, max: 0.8 },
452:           shadowAllocation: 0.15,
453:           transformationSlots: 1,
454:         },
455:         cooldown: {
456:           intensityCeiling: 0.25,
457:           integrationFocus: false,
458:           preferredModalities: ['ImmersiveRPG'],
459:         },
460:       };
461: 
462:     case 'balanced-development':
463:       return {
464:         warmup: {
465:           intensityCeiling: 0.35,
466:           focus: 'general',
467:           preferredModalities: [],
468:         },
469:         peak: {
470:           intensityRange: { min: 0.5, max: 0.8 },
471:           shadowAllocation: 0.2,
472:           transformationSlots: 1,
473:         },
474:         cooldown: {
475:           intensityCeiling: 0.25,
476:           integrationFocus: false,
477:           preferredModalities: ['LanguageReflective'],
478:         },
479:       };
480:   }
481: }
482: 
483: // ---------------------------------------------------------------------------
484: // Encounter budget
485: // ---------------------------------------------------------------------------
486: 
487: /**
488:  * Compute the encounter budget for a session.
489:  * Distributes encounters across warmup (20%), peak (60%), cooldown (20%)
490:  * phases based on the target session length.
491:  */
492: export function computeEncounterBudget(
493:   session: SessionContext,
494:   arc: ParameterisedSessionArc,
495: ): EncounterBudget {
496:   const totalTarget = session.targetSessionLength;
497: 
498:   // Distribute encounters: warmup 20%, peak 60%, cooldown 20%
499:   const warmupCount = Math.max(1, Math.round(totalTarget * 0.2));
500:   const cooldownCount = Math.max(1, Math.round(totalTarget * 0.2));
501:   const peakCount = Math.max(1, totalTarget - warmupCount - cooldownCount);
502: 
503:   // Shadow cap: peak shadow allocation * peak encounter count
504:   const shadowEncounterCap = Math.max(0, Math.round(arc.peak.shadowAllocation * peakCount));
505: 
506:   // Practice slots: 1 for sessions with > 10 encounters, 0 otherwise
507:   const practiceSlots = totalTarget > 10 ? 1 : 0;
508: 
509:   return {
510:     totalTarget,
511:     warmupCount,
512:     peakCount,
513:     cooldownCount,
514:     shadowEncounterCap,
515:     practiceSlots,
516:   };
517: }
518: 
519: // ---------------------------------------------------------------------------
520: // Mid-session adjustment
521: // ---------------------------------------------------------------------------
522: 
523: /**
524:  * Evaluate whether a mid-session strategy adjustment is needed.
525:  * Checks 4 signals: energy drop, avoidance spike, engagement surge,
526:  * and shadow fatigue. Returns null if no adjustment is warranted.
527:  */
528: export function evaluateMidSessionAdjustment(
529:   currentStrategy: SessionStrategy,
530:   session: SessionContext,
531:   recentOutcomes: RecentEncounter[],
532: ): SessionStrategyAdjustment | null {
533:   // Signal 1: Energy drop - reduce intensity when player energy is low
534:   if (session.inferredEnergy === 'low' &&
535:       currentStrategy.arc.peak.intensityRange.max > 0.5) {
536:     return {
537:       type: 'intensity-reduction',
538:       newPeakIntensity: { min: 0.3, max: 0.5 },
539:       rationale: 'Energy drop detected; reducing peak intensity',
540:     };
541:   }
542: 
543:   // Signal 2: Avoidance spike - shift to consolidation when too many encounters avoided
544:   const recentSlice = recentOutcomes.slice(0, 3);
545:   const avoidanceCount = recentSlice.filter(e => e.outcome === 'avoided').length;
546:   const avoidanceRate = recentSlice.length > 0 ? avoidanceCount / recentSlice.length : 0;
547:   if (avoidanceRate > currentStrategy.adjustmentThresholds.avoidanceSpikeThreshold) {
548:     return {
549:       type: 'theme-shift',
550:       newTheme: 'consolidation',
551:       newWeightBias: computeWeightBias('consolidation', null),
552:       rationale: 'High avoidance rate; shifting to consolidation',
553:     };
554:   }
555: 
556:   // Signal 3: Engagement surge - allow intensity increase when quality is high
557:   const recentQuality = recentOutcomes.length > 0
558:     ? recentOutcomes.slice(0, 3).reduce((sum, e) => sum + e.quality, 0) /
559:       Math.min(recentOutcomes.length, 3)
560:     : 0;
561:   if (recentQuality > currentStrategy.adjustmentThresholds.engagementSurgeThreshold &&
562:       session.inferredEnergy === 'high') {
563:     return {
564:       type: 'intensity-increase',
565:       newPeakIntensity: { min: 0.7, max: 1.0 },
566:       rationale: 'High engagement + energy; allowing intensity increase',
567:     };
568:   }
569: 
570:   // Signal 4: Shadow fatigue - pause shadow work when consecutive shadow
571:   // encounters fail to produce integration
572:   const consecutiveShadowFailures = countConsecutiveShadowFailures(recentOutcomes);
573:   if (consecutiveShadowFailures >= currentStrategy.adjustmentThresholds.shadowFatigueTrials) {
574:     return {
575:       type: 'shadow-pause',
576:       shadowBiasOverride: 0.3,
577:       rationale: 'Shadow fatigue; reducing shadow encounter frequency',
578:     };
579:   }
580: 
581:   return null;
582: }
583: 
584: // ---------------------------------------------------------------------------
585: // Safety override
586: // ---------------------------------------------------------------------------
587: 
588: /**
589:  * Check whether a safety override should engage.
590:  * Returns true if the Significator shows multiple distress signals:
591:  * high fixation risk AND heavy unresolved shadows AND low intensity budget.
592:  * When true, the caller should force 'consolidation' theme.
593:  */
594: export function checkSafetyOverride(snapshot: SignificatorSnapshot): boolean {
595:   const maxFixationRisk = Math.max(
596:     ...Object.values(snapshot.fixationRisk),
597:   );
598:   const unresolvedShadows = snapshot.shadows.entries.filter(
599:     e => e.resolvedAt === null,
600:   ).length;
601: 
602:   // Import from the CCI logic: if fixation > 0.8 AND shadows > 10 => distressed
603:   // The intensity budget check is implicit: these conditions produce < 0.3 budget
604:   return maxFixationRisk > 0.8 && unresolvedShadows > 10;
605: }
606: 
607: // ---------------------------------------------------------------------------
608: // Internal helpers
609: // ---------------------------------------------------------------------------
610: 
611: /**
612:  * Count consecutive shadow-mode encounters without integration from
613:  * the most recent outcomes backwards.
614:  */
615: function countConsecutiveShadowFailures(outcomes: RecentEncounter[]): number {
616:   let count = 0;
617:   for (const outcome of outcomes) {
618:     if (outcome.mode === 'shadow' && !outcome.shadowIntegrated) {
619:       count++;
620:     } else {
621:       break;
622:     }
623:   }
624:   return count;
625: }
626: 
627: /**
628:  * Compute modality bias for a given theme.
629:  * Returns partial record of modality multipliers. Empty means no bias.
630:  */
631: function computeModalityBias(theme: SessionTheme): Partial<Record<string, number>> {
632:   switch (theme) {
633:     case 'shadow-integration':
634:       return {
635:         'LanguageReflective': 1.4,
636:         'ImmersiveRPG': 1.2,
637:         'ScenarioChoice': 1.1,
638:         'Deterministic': 0.7,
639:       };
640:     case 'growth-edge-push':
641:       return {
642:         'Deterministic': 1.3,
643:         'Strategic': 1.3,
644:         'ScenarioChoice': 1.1,
645:       };
646:     case 'consolidation':
647:       return {
648:         'Deterministic': 1.2,
649:         'LanguageReflective': 1.1,
650:         'ImmersiveRPG': 1.1,
651:       };
652:     case 'drive-rebalancing':
653:       return {
654:         'ScenarioChoice': 1.3,
655:         'SocialCooperative': 1.3,
656:         'ImmersiveRPG': 1.1,
657:       };
658:     case 'transformation-prep':
659:       return {
660:         'Strategic': 1.2,
661:         'ScenarioChoice': 1.2,
662:         'LanguageReflective': 1.1,
663:       };
664:     case 'active-transformation':
665:       return {
666:         'ImmersiveRPG': 1.5,
667:         'ScenarioChoice': 1.3,
668:       };
669:     case 'post-transformation':
670:       return {
671:         'ImmersiveRPG': 1.3,
672:         'LanguageReflective': 1.2,
673:         'ScenarioChoice': 1.1,
674:       };
675:     case 'polarity-deepening':
676:       return {
677:         'ScenarioChoice': 1.4,
678:         'LanguageReflective': 1.2,
679:         'SocialCooperative': 1.1,
680:       };
681:     case 'balanced-development':
682:       return {};
683:   }
684: }
685: 
686: /**
687:  * Post-transformation weight ramp-up.
688:  * For 5 sessions after transformation, use post-transformation weights.
689:  * For sessions 6-10, linearly interpolate back to defaults.
690:  * Spec: foundations/17 §5.2, foundations/24 §6.3
691:  */
692: export function computePostTransformationBias(
693:   sessionsSinceTransformation: number,
694: ): PriorityWeightBias | null {
695:   if (sessionsSinceTransformation >= 10) return null;
696: 
697:   const postWeights: PriorityWeightBias = {
698:     thetaUrgency: -0.10,
699:     shadowActivation: -0.05,
700:     polarityAlignment: 0.05,
701:     transformationReadiness: -0.10,
702:     driveCorrection: 0.05,
703:     narrativeCoherence: 0.10,
704:     sessionFit: 0.05,
705:   };
706: 
707:   if (sessionsSinceTransformation < 5) return postWeights;
708: 
709:   const t = (sessionsSinceTransformation - 5) / 5;
710:   const result: PriorityWeightBias = {
711:     thetaUrgency: postWeights.thetaUrgency * (1 - t),
712:     shadowActivation: postWeights.shadowActivation * (1 - t),
713:     polarityAlignment: postWeights.polarityAlignment * (1 - t),
714:     transformationReadiness: postWeights.transformationReadiness * (1 - t),
715:     driveCorrection: postWeights.driveCorrection * (1 - t),
716:     narrativeCoherence: postWeights.narrativeCoherence * (1 - t),
717:     sessionFit: postWeights.sessionFit * (1 - t),
718:   };
719:   return result;
720: }

