1: /**
2:  * Assessment Engine - pure functions for scoring and aggregation.
3:  * Spec: docs/STAGE-ASSESSMENT-ARCHITECTURE Part V.
4:  *
5:  * All functions are pure: state in, result out. No side effects.
6:  */
7: import type {
8:   StageAssessment,
9:   TrialResult,
10:   AssessmentResult,
11:   ScoringRubric,
12:   MeasureDimension,
13:   ModuleExecutionMode,
14:   ShadowAssessmentResult,
15: } from './types.js';
16: import type { Drive } from '../domain/Drive.js';
17: 
18: const ALL_DIMENSIONS: readonly MeasureDimension[] = [
19:   'accuracy',
20:   'response_time',
21:   'consistency',
22:   'depth',
23:   'self_correction',
24:   'complexity_handled',
25:   'transfer',
26:   'metacognition',
27:   'coherence',
28:   'integration',
29: ];
30: 
31: /**
32:  * Compute weighted average for each dimension across trials.
33:  * Dimensions not present in a trial are excluded from that trial's contribution.
34:  * Weights from the rubric determine each dimension's importance in the final score.
35:  */
36: export function scoreTrials(
37:   trials: readonly TrialResult[],
38:   _rubric: ScoringRubric,
39: ): Record<MeasureDimension, number> {
40:   const result = {} as Record<MeasureDimension, number>;
41: 
42:   for (const dim of ALL_DIMENSIONS) {
43:     const values: number[] = [];
44:     for (const trial of trials) {
45:       const v = trial.dimensions[dim];
46:       if (v !== undefined) {
47:         values.push(v);
48:       }
49:     }
50:     if (values.length === 0) {
51:       result[dim] = 0;
52:     } else {
53:       const sum = values.reduce((a, b) => a + b, 0);
54:       result[dim] = sum / values.length;
55:     }
56:   }
57: 
58:   return result;
59: }
60: 
61: /**
62:  * Compute confidence in the pass/fail determination.
63:  * Formula: distance * consistency * trialFactor
64:  *   - distance: normalized distance of weighted score from threshold
65:  *   - consistency: 1 - variance of dimension scores across trials
66:  *   - trialFactor: min(1, trials.length / 6) - more trials = more confidence
67:  */
68: export function computeConfidence(
69:   trials: readonly TrialResult[],
70:   passThreshold: number,
71: ): number {
72:   if (trials.length === 0) return 0;
73: 
74:   // Compute weighted score across all trials (average of all dimensions present)
75:   const trialScores: number[] = [];
76:   for (const trial of trials) {
77:     const values = Object.values(trial.dimensions).filter(
78:       (v): v is number => v !== undefined,
79:     );
80:     if (values.length > 0) {
81:       trialScores.push(values.reduce((a, b) => a + b, 0) / values.length);
82:     }
83:   }
84: 
85:   if (trialScores.length === 0) return 0;
86: 
87:   const mean = trialScores.reduce((a, b) => a + b, 0) / trialScores.length;
88: 
89:   // distance: how far from the threshold (normalized 0-1)
90:   const distance = Math.min(1, Math.abs(mean - passThreshold));
91: 
92:   // consistency: 1 - variance (clamped to 0-1)
93:   const variance =
94:     trialScores.length > 1
95:       ? trialScores.reduce((sum, s) => sum + (s - mean) ** 2, 0) / trialScores.length
96:       : 0;
97:   const consistency = Math.max(0, 1 - variance);
98: 
99:   // trialFactor: more trials increases confidence, saturates at 6
100:   const trialFactor = Math.min(1, trials.length / 6);
101: 
102:   return distance * consistency * trialFactor;
103: }
104: 
105: /**
106:  * Run an assessment by aggregating trial results against a module's rubric.
107:  * Returns a full AssessmentResult with pass/fail determination.
108:  */
109: export function runAssessment(
110:   module: StageAssessment,
111:   trials: readonly TrialResult[],
112: ): AssessmentResult {
113:   const rubric = module.scoringRubric;
114:   const dimensions = scoreTrials(trials, rubric);
115: 
116:   // Compute weighted score using rubric dimension weights
117:   let weightedSum = 0;
118:   let totalWeight = 0;
119:   for (const dim of ALL_DIMENSIONS) {
120:     const weight = rubric.dimensionWeights[dim] ?? 0;
121:     if (weight > 0) {
122:       weightedSum += dimensions[dim] * weight;
123:       totalWeight += weight;
124:     }
125:   }
126: 
127:   const weightedScore = totalWeight > 0 ? weightedSum / totalWeight : 0;
128:   const passed = weightedScore >= rubric.passThreshold;
129:   const confidence = computeConfidence(trials, rubric.passThreshold);
130: 
131:   return {
132:     line: module.line,
133:     stage: module.stage,
134:     passed,
135:     confidence,
136:     dimensions,
137:     rawTrials: trials,
138:   };
139: }
140: 
141: // ─── Mode-Aware Assessment Functions ────────────────────────────────────────
142: 
143: /**
144:  * Mode-aware assessment runner. Dispatches to the appropriate scoring path
145:  * based on execution mode.
146:  */
147: export function runModeAwareAssessment(
148:   module: StageAssessment,
149:   trials: readonly TrialResult[],
150:   mode: ModuleExecutionMode,
151: ): AssessmentResult | ShadowAssessmentResult {
152:   switch (mode) {
153:     case 'shadow':
154:       return runShadowAssessment(module, trials);
155:     case 'calibration':
156:       return runCalibrationAssessment(module, trials);
157:     case 'practice':
158:     case 'capacity':
159:     default:
160:       return runAssessment(module, trials);
161:   }
162: }
163: 
164: /**
165:  * Shadow mode assessment: scores drive-health per drive per domain.
166:  * Produces ShadowAssessmentResult with driveHealth, severity, and dominant pathology.
167:  */
168: export function runShadowAssessment(
169:   module: StageAssessment,
170:   trials: readonly TrialResult[],
171: ): ShadowAssessmentResult {
172:   const baseResult = runAssessment(module, trials);
173: 
174:   // Map trials to drive probes by matching task IDs
175:   const driveProbeTaskIds = {
176:     agency: module.driveProbes.agency.task.id,
177:     communion: module.driveProbes.communion.task.id,
178:     eros: module.driveProbes.eros.task.id,
179:     agape: module.driveProbes.agape.task.id,
180:   };
181: 
182:   const driveHealth = computeDriveHealth(trials, driveProbeTaskIds);
183:   const darkShadowSeverity = Math.max(
184:     1 - driveHealth.agency.dark,
185:     1 - driveHealth.communion.dark,
186:     1 - driveHealth.eros.dark,
187:     1 - driveHealth.agape.dark,
188:   );
189:   const goldenShadowSeverity = Math.max(
190:     1 - driveHealth.agency.golden,
191:     1 - driveHealth.communion.golden,
192:     1 - driveHealth.eros.golden,
193:     1 - driveHealth.agape.golden,
194:   );
195: 
196:   const dominantPathology = identifyDominantPathology(driveHealth);
197: 
198:   return {
199:     ...baseResult,
200:     driveHealth,
201:     darkShadowSeverity,
202:     goldenShadowSeverity,
203:     dominantPathology,
204:   };
205: }
206: 
207: /**
208:  * Calibration mode: same as capacity but enforces minimum trials.
209:  */
210: function runCalibrationAssessment(
211:   module: StageAssessment,
212:   trials: readonly TrialResult[],
213: ): AssessmentResult {
214:   const result = runAssessment(module, trials);
215:   // In calibration, confidence is penalised if below minimum trials
216:   const trialPenalty = trials.length < module.minimumTrials
217:     ? trials.length / module.minimumTrials
218:     : 1;
219:   return {
220:     ...result,
221:     confidence: result.confidence * trialPenalty,
222:   };
223: }
224: 
225: type DriveHealthScores = ShadowAssessmentResult['driveHealth'];
226: 
227: /**
228:  * Compute per-drive per-domain health scores from trial results.
229:  * Each drive probe trial's dimensions are averaged to produce a health score.
230:  * Dark domain = how well the player relates to current/past capacity.
231:  * Golden domain = how well the player relates to next-stage capacity.
232:  * Score of 1.0 = healthy, 0.0 = severely pathological.
233:  */
234: function computeDriveHealth(
235:   trials: readonly TrialResult[],
236:   probeTaskIds: Record<string, string>,
237: ): DriveHealthScores {
238:   const drives = ['agency', 'communion', 'eros', 'agape'] as const;
239:   const result = {} as Record<string, { dark: number; golden: number }>;
240: 
241:   for (const drive of drives) {
242:     const probeTrials = trials.filter(t => t.taskId === probeTaskIds[drive]);
243:     if (probeTrials.length === 0) {
244:       // No probe data — assume healthy (0.7 baseline)
245:       result[drive] = { dark: 0.7, golden: 0.7 };
246:       continue;
247:     }
248: 
249:     // Average all dimension values for this drive's trials
250:     const scores = probeTrials.map(t => {
251:       const vals = Object.values(t.dimensions).filter((v): v is number => v !== undefined);
252:       return vals.length > 0 ? vals.reduce((a, b) => a + b, 0) / vals.length : 0.5;
253:     });
254:     const avgScore = scores.reduce((a, b) => a + b, 0) / scores.length;
255: 
256:     // Dark domain: score directly (high = healthy relationship to current)
257:     // Golden domain: derived from consistency + depth (high = healthy relationship to growth)
258:     const consistency = probeTrials.length > 1
259:       ? 1 - Math.sqrt(scores.reduce((sum, s) => sum + (s - avgScore) ** 2, 0) / scores.length)
260:       : 0.7;
261: 
262:     result[drive] = {
263:       dark: Math.max(0, Math.min(1, avgScore)),
264:       golden: Math.max(0, Math.min(1, (avgScore + consistency) / 2)),
265:     };
266:   }
267: 
268:   return result as DriveHealthScores;
269: }
270: 
271: /**
272:  * Identify the most pathological drive and its domain/type.
273:  */
274: function identifyDominantPathology(
275:   driveHealth: DriveHealthScores,
276: ): ShadowAssessmentResult['dominantPathology'] {
277:   const drives: Drive[] = ['Agency', 'Communion', 'Eros', 'Agape'];
278:   const driveKeys = ['agency', 'communion', 'eros', 'agape'] as const;
279: 
280:   let worstDrive: Drive = 'Agency';
281:   let worstDomain: 'dark' | 'golden' = 'dark';
282:   let worstScore = 1;
283: 
284:   for (let i = 0; i < 4; i++) {
285:     const key = driveKeys[i];
286:     const health = driveHealth[key];
287:     if (health.dark < worstScore) {
288:       worstScore = health.dark;
289:       worstDrive = drives[i];
290:       worstDomain = 'dark';
291:     }
292:     if (health.golden < worstScore) {
293:       worstScore = health.golden;
294:       worstDrive = drives[i];
295:       worstDomain = 'golden';
296:     }
297:   }
298: 
299:   // Only report pathology if score is below 0.5 (developing or worse)
300:   if (worstScore >= 0.5) return null;
301: 
302:   // Determine addiction vs allergy:
303:   // Addiction = high agency/eros but low communion/agape (over-doing)
304:   // Allergy = low agency/eros but high communion/agape (under-doing)
